args.source:
import type { Plugin } from "../../kernel/types";

const plugin: Plugin = {
  id: "local-provider",
  name: "Local Provider",
  version: "1.0.0",
  onLoad(ctx) {
    ctx.register({
      kind: "provider",
      provider: {
        id: "local-response",
        label: "Local",
        defaultModel: "local",
        models: [{ id: "local", label: "Local" }],
        async *chat(request: any, pctx: any) {
          yield { type: "delta", text: "LOCAL-OK" };
          yield { type: "usage", input: 1, output: 1 };
          yield { type: "done" };
        },
      },
    });
  },
};

export default plugin;

